def is_valid(board, row, col, num):
    # Check row
    for i in range(9):
        if board[row][i] == num:
            return False

    # Check column
    for i in range(9):
        if board[i][col] == num:
            return False

    # Check 3x3 box
    box_row = row - row % 3
    box_col = col - col % 3
    for i in range(box_row, box_row + 3):
        for j in range(box_col, box_col + 3):
            if board[i][j] == num:
                return False

    return True

def solve_sudoku(board):
    # Find an empty cell
    empty = None
    for row in range(9):
        for col in range(9):
            if board[row][col] == 0:
                empty = (row, col)
                break
        if empty is not None:
            break

    if empty is None:
        return True
    else:
        row, col = empty

    # Try each number in the row, column, and box
    for num in range(1, 10):
        if is_valid(board, row, col, num):
            board[row][col] = num

            # If the puzzle is solved, return True
            if solve_sudoku(board):
                return True

            # If the puzzle is not solved, backtrack
            board[row][col] = 0

    return False

def print_board(board):
    for row in board:
        print(' '.join(str(cell) for cell in row))

